sys_script_include.script:
var TrainingUtils = Class.create();
TrainingUtils.prototype = {
    initialize: function() {},

    refQualTraining: function() {
        var enrolledSchedules = [];
        var enrolledCourses = [];
        var availableCourses = []; // Novo array para armazenar cursos disponíveis


        var grEnrollment = new GlideRecord("x_1593183_traini_0_training_enrollments");
        grEnrollment.addQuery("opened_by", gs.getUserID());
        grEnrollment.query();

        while (grEnrollment.next()) {
            enrolledSchedules.push(grEnrollment.getValue("schedule"));
            enrolledCourses.push(grEnrollment.getValue("course"));
        }

        var availableSchedules = [];
        var grSchedules = new GlideRecord("x_1593183_traini_0_training_schedules");
        grSchedules.addQuery("status", "1"); // Apenas agendamentos ativos
        grSchedules.query();

        while (grSchedules.next()) {
            var scheduleId = grSchedules.getUniqueValue();
            var courseId = grSchedules.getValue("course");

            // Verificar se o usuário já se inscreveu 3 vezes neste curso
            var enrollmentCount = 0;
            var grCount = new GlideRecord("x_1593183_traini_0_training_enrollments");
            grCount.addQuery("opened_by", gs.getUserID());
            grCount.addQuery("course", courseId);
            grCount.query();

            while (grCount.next()) {
                enrollmentCount++;
            }

            if (enrollmentCount >= 3) {
                gs.info("⚠️ Usuário já atingiu o limite de 3 inscrições no curso: " + courseId);
                continue;
            }
			gs.info("curso" + courseId + "chegou aqui.");

            if (!enrolledSchedules.includes(scheduleId)) {
                availableSchedules.push(scheduleId);

                // Adicionar curso à lista de disponíveis (sem duplicatas)
                if (!availableCourses.includes(courseId)) {
                    availableCourses.push(courseId);
                }
            }
        }

        gs.info("✅ Cursos disponíveis: " + availableCourses.join(", "));

        return {
            schedules: availableSchedules.length > 0 ? "sys_idIN" + availableSchedules.join(",") : "sys_idINEMPTY",
            courses: "sys_idIN" + availableCourses.join(",") // Retorna a lista de cursos disponíveis
        };
    },
	type : 'TrainingUtils'
};
